{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Carbamazepine epoxide, a close structural analogue retaining the tricyclic carbamoyl framework, has an absolute oral bioavailability of 60% in healthy subjects, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Oxcarbazepine, the 10-keto analogue of the same dibenzazepine scaffold, has an absolute oral bioavailability of >95% in humans, strongly supporting high oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Licarbazepine, the reduced metabolite analogue, has a mean absolute bioavailability of 89% after oral dosing in healthy adults, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Eslicarbazepine, the chiral hydroxy analogue, has approximately 94% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Eslicarbazepine acetate shows >90% oral bioavailability and food co-ingestion does not affect absorption/bioavailability, supporting high F under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Phenylethylmalonamide, a lower-similarity acyclic analogue, has an absolute bioavailability of 91%, providing weaker but consistent support for high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is carbamazepine. Close structural analogues—carbamazepine epoxide, oxcarbazepine, licarbazepine, eslicarbazepine, and eslicarbazepine acetate—consistently show absolute oral bioavailability values of 60% to >95%, all well above the 20% threshold. The only poor-bioavailability analogue (zileuton) is structurally distant and does not transfer. Therefore the prediction is high oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for carbamazepine itself under fed conditions is present in the provided records; extrapolation relies on close analogues.",
    "Explicit fed-state bioavailability data are available for eslicarbazepine acetate, but not for carbamazepine itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

